1	// Tank Arena engine. Pure, deterministic, no DOM and no Node APIs:
2	// the same file drives the CLI sandbox and the browser viewer.
3	
4	export const TICK_RATE = 30;
5	export const DT = 1 / TICK_RATE;
6	export const ARENA = { width: 1600, height: 900 };
7	export const ROUND_SECONDS = 120;
8	export const TANK_RADIUS = 24;
9	export const BULLET_RADIUS = 5;
10	export const BULLET_LIFETIME = 4;
11	export const BULLET_BOUNCES = 1;
12	export const MUZZLE_OFFSET = TANK_RADIUS + 10;
13	export const TURRET_RATE = 2.8;
14	export const ACCEL = 420;
15	export const REVERSE_FACTOR = 0.6;
16	export const KIT = { radius: 16, heal: 50, firstSpawn: 15, respawn: 20 };
17	export const ZONE = { startShrink: 60, endShrink: 100, finalRadius: 170, damagePerSecond: 20 };
18	export const STAT_POINTS = 10;
19	export const STAT_MAX = 5;
20	export const STAT_KEYS = ['armor', 'engine', 'gun', 'reload'];
21	export const DEFAULT_STATS = { armor: 3, engine: 3, gun: 2, reload: 2 };
22	
23	const W = ARENA.width;
24	const H = ARENA.height;
25	const ZONE_START_RADIUS = Math.hypot(W / 2, H / 2) + 60;
26	
27	// ---------- stats ----------
28	
29	export function checkStats(stats) {
30	  if (!stats || typeof stats !== 'object') return { ok: false, error: 'stats не заданы' };
31	  let total = 0;
32	  for (const k of STAT_KEYS) {
33	    const v = stats[k];
34	    if (!Number.isInteger(v) || v < 0 || v > STAT_MAX) {
35	      return { ok: false, error: `stats.${k} должно быть целым от 0 до ${STAT_MAX}` };
36	    }
37	    total += v;
38	  }
39	  if (total > STAT_POINTS) return { ok: false, error: `сумма очков ${total} больше ${STAT_POINTS}` };
40	  return { ok: true, total };
41	}
42	
43	export function deriveStats(stats) {
44	  const s = checkStats(stats).ok ? stats : DEFAULT_STATS;
45	  return {
46	    armor: s.armor,
47	    engine: s.engine,
48	    gun: s.gun,
49	    reload: s.reload,
50	    maxHp: 100 + 25 * s.armor,
51	    maxSpeed: 110 + 22 * s.engine,
52	    turnRate: 1.8 + 0.25 * s.engine,
53	    turretRate: TURRET_RATE,
54	    damage: 18 + 5 * s.gun,
55	    bulletSpeed: 450 + 50 * s.gun,
56	    reloadTime: Math.round((1.3 - 0.16 * s.reload) * 100) / 100,
57	  };
58	}
59	
60	// ---------- maps ----------
61	// Every map is point-symmetric around the centre, so both spawns are equal.
62	
63	function mirrorWall(w) {
64	  return { x: W - w.x - w.w, y: H - w.y - w.h, w: w.w, h: w.h };
65	}
66	
67	function buildMap(name, half, kits) {
68	  const walls = [];
69	  for (const w of half) walls.push({ ...w }, mirrorWall(w));
70	  return {
71	    name,
72	    walls,
73	    spawns: [
74	      { x: 140, y: H / 2, heading: 0 },
75	      { x: W - 140, y: H / 2, heading: Math.PI },
76	    ],
77	    kits,
78	  };
79	}
80	
81	export const MAPS = [
82	  buildMap('Полигон', [
83	    { x: 330, y: 160, w: 44, h: 200 },
84	    { x: 330, y: 540, w: 44, h: 200 },
85	    { x: 600, y: 300, w: 160, h: 44 },
86	    { x: 770, y: 390, w: 30, h: 120 },
87	  ], [{ x: 800, y: 130 }, { x: 800, y: 770 }]),
88	  buildMap('Лабиринт', [
89	    { x: 250, y: 250, w: 40, h: 400 },
90	    { x: 450, y: 0, w: 40, h: 330 },
91	    { x: 450, y: 570, w: 40, h: 330 },
92	    { x: 640, y: 200, w: 200, h: 40 },
93	    { x: 780, y: 330, w: 20, h: 240 },
94	  ], [{ x: 800, y: 110 }, { x: 800, y: 790 }]),
95	  buildMap('Крепости', [
96	    { x: 230, y: 330, w: 40, h: 240 },
97	    { x: 90, y: 290, w: 180, h: 40 },
98	    { x: 90, y: 570, w: 180, h: 40 },
99	    { x: 560, y: 120, w: 44, h: 220 },
100	    { x: 560, y: 560, w: 44, h: 220 },
101	    { x: 740, y: 420, w: 60, h: 60 },
102	  ], [{ x: 800, y: 130 }, { x: 800, y: 770 }]),
103	  buildMap('Каньон', [
104	    { x: 300, y: 280, w: 420, h: 40 },
105	    { x: 300, y: 580, w: 260, h: 40 },
106	    { x: 780, y: 110, w: 40, h: 160 },
107	  ], [{ x: 620, y: 450 }, { x: 980, y: 450 }]),
108	];
109	
110	// Round i of a match: maps rotate, and every map is played from both sides.
111	export function roundPlan(i) {
112	  return { mapIndex: i % MAPS.length, swap: (i + Math.floor(i / MAPS.length)) % 2 === 1 };
113	}
114	
115	// ---------- geometry ----------
116	
117	const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
118	
119	export function normalizeAngle(a) {
120	  a = (a + Math.PI) % (2 * Math.PI);
121	  if (a < 0) a += 2 * Math.PI;
122	  return a - Math.PI;
123	}
124	
125	function circleRect(cx, cy, r, w) {
126	  const px = clamp(cx, w.x, w.x + w.w);
127	  const py = clamp(cy, w.y, w.y + w.h);
128	  const dx = cx - px;
129	  const dy = cy - py;
130	  const d2 = dx * dx + dy * dy;
131	  if (d2 >= r * r) return null;
132	  if (d2 > 1e-9) {
133	    const d = Math.sqrt(d2);
134	    return { nx: dx / d, ny: dy / d, depth: r - d };
135	  }
136	  const left = cx - w.x;
137	  const right = w.x + w.w - cx;
138	  const top = cy - w.y;
139	  const bottom = w.y + w.h - cy;
140	  const m = Math.min(left, right, top, bottom);
141	  if (m === left) return { nx: -1, ny: 0, depth: left + r };
142	  if (m === right) return { nx: 1, ny: 0, depth: right + r };
143	  if (m === top) return { nx: 0, ny: -1, depth: top + r };
144	  return { nx: 0, ny: 1, depth: bottom + r };
145	}
146	
147	function boundsHit(x, y, r) {
148	  if (x < r) return { nx: 1, ny: 0, depth: r - x };
149	  if (x > W - r) return { nx: -1, ny: 0, depth: x - (W - r) };
150	  if (y < r) return { nx: 0, ny: 1, depth: r - y };
151	  if (y > H - r) return { nx: 0, ny: -1, depth: y - (H - r) };
152	  return null;
153	}
154	
155	// ---------- round ----------
156	
157	function sanitizeAction(a) {
158	  const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? clamp(v, -1, 1) : 0);
159	  if (!a || typeof a !== 'object') return { throttle: 0, turn: 0, turretTurn: 0, fire: false };
160	  return { throttle: num(a.throttle), turn: num(a.turn), turretTurn: num(a.turretTurn), fire: !!a.fire };
161	}
162	
163	function emptyTally() {
164	  return { shots: 0, hits: 0, damageDealt: 0, damageTaken: 0, selfDamage: 0, ricochetHits: 0, intercepts: 0, kits: 0, zoneDamage: 0 };
165	}
166	
167	export function createRound({ mapIndex = 0, tanks }) {
168	  const map = MAPS[mapIndex % MAPS.length];
169	  return {
170	    tick: 0,
171	    time: 0,
172	    mapIndex: mapIndex % MAPS.length,
173	    map,
174	    nextBulletId: 1,
175	    tanks: tanks.map((t, side) => {
176	      const st = deriveStats(t.stats);
177	      const sp = map.spawns[side];
178	      return {
179	        side,
180	        name: t.name,
181	        stats: st,
182	        x: sp.x,
183	        y: sp.y,
184	        heading: sp.heading,
185	        turret: sp.heading,
186	        speed: 0,
187	        hp: st.maxHp,
188	        reloadLeft: 0,
189	        alive: true,
190	        tally: emptyTally(),
191	      };
192	    }),
193	    bullets: [],
194	    kits: map.kits.map((k) => ({ x: k.x, y: k.y, active: false, respawnIn: KIT.firstSpawn })),
195	    zone: { x: W / 2, y: H / 2, radius: ZONE_START_RADIUS },
196	    over: false,
197	    winner: null,
198	    endReason: null,
199	  };
200	}
201	
202	function zoneRadiusAt(t) {
203	  if (t <= ZONE.startShrink) return ZONE_START_RADIUS;
204	  const k = clamp((t - ZONE.startShrink) / (ZONE.endShrink - ZONE.startShrink), 0, 1);
205	  return ZONE_START_RADIUS + (ZONE.finalRadius - ZONE_START_RADIUS) * k;
206	}
207	
208	function tankView(t) {
209	  return {
210	    x: t.x,
211	    y: t.y,
212	    heading: t.heading,
213	    turret: t.turret,
214	    speed: t.speed,
215	    vx: Math.cos(t.heading) * t.speed,
216	    vy: Math.sin(t.heading) * t.speed,
217	    hp: t.hp,
218	    maxHp: t.stats.maxHp,
219	    reloadLeft: t.reloadLeft,
220	    alive: t.alive,
221	    stats: { ...t.stats },
222	  };
223	}
224	
225	// What a bot sees on its turn. Always a fresh object: bots cannot touch engine state.
226	export function botView(round, side) {
227	  return {
228	    tick: round.tick,
229	    time: round.time,
230	    timeLeft: Math.max(0, ROUND_SECONDS - round.time),
231	    dt: DT,
232	    side,
233	    arena: {
234	      width: W,
235	      height: H,
236	      mapName: round.map.name,
237	      walls: round.map.walls.map((w) => ({ ...w })),
238	    },
239	    me: tankView(round.tanks[side]),
240	    enemy: tankView(round.tanks[1 - side]),
241	    bullets: round.bullets.map((b) => ({
242	      id: b.id,
243	      x: b.x,
244	      y: b.y,
245	      vx: b.vx,
246	      vy: b.vy,
247	      mine: b.owner === side,
248	      bouncesLeft: b.bouncesLeft,
249	      damage: b.damage,
250	      canHitOwner: b.bounced,
251	    })),
252	    repairKits: round.kits.map((k) => ({ ...k })),
253	    zone: {
254	      x: round.zone.x,
255	      y: round.zone.y,
256	      radius: round.zone.radius,
257	      finalRadius: ZONE.finalRadius,
258	      shrinkStart: ZONE.startShrink,
259	      shrinkEnd: ZONE.endShrink,
260	      damagePerSecond: ZONE.damagePerSecond,
261	    },
262	  };
263	}
264	
265	function damageTank(round, victim, amount, events, info) {
266	  if (!victim.alive || amount <= 0) return;
267	  const dealt = Math.min(victim.hp, amount);
268	  victim.hp -= amount;
269	  victim.tally.damageTaken += dealt;
270	  events.push({ type: 'hit', side: victim.side, x: victim.x, y: victim.y, damage: dealt, ...info });
271	  if (victim.hp <= 0) {
272	    victim.hp = 0;
273	    victim.alive = false;
274	    victim.speed = 0;
275	    events.push({ type: 'death', side: victim.side, x: victim.x, y: victim.y, cause: info.cause });
276	  }
277	}
278	
279	function moveTank(round, t, a) {
280	  const st = t.stats;
281	  t.heading = normalizeAngle(t.heading + a.turn * st.turnRate * DT);
282	  t.turret = normalizeAngle(t.turret + a.turretTurn * st.turretRate * DT);
283	  const target = a.throttle >= 0 ? a.throttle * st.maxSpeed : a.throttle * st.maxSpeed * REVERSE_FACTOR;
284	  const dv = clamp(target - t.speed, -ACCEL * DT, ACCEL * DT);
285	  t.speed += dv;
286	  t.x += Math.cos(t.heading) * t.speed * DT;
287	  t.y += Math.sin(t.heading) * t.speed * DT;
288	}
289	
290	function resolveTankWalls(round, t, events) {
291	  let bumped = false;
292	  for (let pass = 0; pass < 2; pass++) {
293	    for (const w of round.map.walls) {
294	      const c = circleRect(t.x, t.y, TANK_RADIUS, w);
295	      if (c) {
296	        t.x += c.nx * c.depth;
297	        t.y += c.ny * c.depth;
298	        bumped = true;
299	      }
300	    }
301	    const nx = clamp(t.x, TANK_RADIUS, W - TANK_RADIUS);
302	    const ny = clamp(t.y, TANK_RADIUS, H - TANK_RADIUS);
303	    if (nx !== t.x || ny !== t.y) bumped = true;
304	    t.x = nx;
305	    t.y = ny;
306	  }
307	  if (bumped && Math.abs(t.speed) > 60) events.push({ type: 'bump', side: t.side, x: t.x, y: t.y });
308	  if (bumped) t.speed *= 0.6;
309	}
310	
311	function resolveTankTank(a, b) {
312	  if (!a.alive && !b.alive) return;
313	  const dx = b.x - a.x;
314	  const dy = b.y - a.y;
315	  const d = Math.hypot(dx, dy);
316	  const min = TANK_RADIUS * 2;
317	  if (d >= min || d < 1e-6) return;
318	  const push = (min - d) / 2;
319	  const nx = dx / d;
320	  const ny = dy / d;
321	  // A wreck does not move; the living tank takes the whole push.
322	  const pa = a.alive ? (b.alive ? push : push * 2) : 0;
323	  const pb = b.alive ? (a.alive ? push : push * 2) : 0;
324	  a.x -= nx * pa;
325	  a.y -= ny * pa;
326	  b.x += nx * pb;
327	  b.y += ny * pb;
328	}
329	
330	function fire(round, t, events) {
331	  const dx = Math.cos(t.turret);
332	  const dy = Math.sin(t.turret);
333	  const x = t.x + dx * MUZZLE_OFFSET;
334	  const y = t.y + dy * MUZZLE_OFFSET;
335	  t.reloadLeft = t.stats.reloadTime;
336	  t.tally.shots++;
337	  events.push({ type: 'shot', side: t.side, x, y, angle: t.turret });
338	  const blocked = boundsHit(x, y, BULLET_RADIUS) || round.map.walls.some((w) => circleRect(x, y, BULLET_RADIUS, w));
339	  if (blocked) {
340	    events.push({ type: 'impact', x, y, owner: t.side });
341	    return;
342	  }
343	  round.bullets.push({
344	    id: round.nextBulletId++,
345	    owner: t.side,
346	    x,
347	    y,
348	    vx: dx * t.stats.bulletSpeed,
349	    vy: dy * t.stats.bulletSpeed,
350	    damage: t.stats.damage,
351	    bouncesLeft: BULLET_BOUNCES,
352	    bounced: false,
353	    age: 0,
354	    dead: false,
355	  });
356	}
357	
358	function stepBullets(round, events) {
359	  for (const b of round.bullets) {
360	    if (b.dead) continue;
361	    b.age += DT;
362	    if (b.age > BULLET_LIFETIME) {
363	      b.dead = true;
364	      events.push({ type: 'fizzle', x: b.x, y: b.y, owner: b.owner });
365	      continue;
366	    }
367	    const speed = Math.hypot(b.vx, b.vy);
368	    const steps = Math.max(1, Math.ceil((speed * DT) / 6));
369	    const sdt = DT / steps;
370	    for (let s = 0; s < steps && !b.dead; s++) {
371	      b.x += b.vx * sdt;
372	      b.y += b.vy * sdt;
373	      let c = boundsHit(b.x, b.y, BULLET_RADIUS);
374	      if (!c) {
375	        for (const w of round.map.walls) {
376	          c = circleRect(b.x, b.y, BULLET_RADIUS, w);
377	          if (c) break;
378	        }
379	      }
380	      if (c) {
381	        if (b.bouncesLeft > 0) {
382	          b.bouncesLeft--;
383	          b.bounced = true;
384	          b.x += c.nx * c.depth;
385	          b.y += c.ny * c.depth;
386	          const dot = b.vx * c.nx + b.vy * c.ny;
387	          b.vx -= 2 * dot * c.nx;
388	          b.vy -= 2 * dot * c.ny;
389	          events.push({ type: 'ricochet', x: b.x, y: b.y, owner: b.owner, nx: c.nx, ny: c.ny });
390	        } else {
391	          b.dead = true;
392	          events.push({ type: 'impact', x: b.x, y: b.y, owner: b.owner });
393	        }
394	        continue;
395	      }
396	      for (const t of round.tanks) {
397	        if (!t.alive) continue;
398	        if (t.side === b.owner && !b.bounced) continue;
399	        if (Math.hypot(t.x - b.x, t.y - b.y) < TANK_RADIUS + BULLET_RADIUS) {
400	          b.dead = true;
401	          const shooter = round.tanks[b.owner];
402	          const self = t.side === b.owner;
403	          const dealt = Math.min(t.hp, b.damage);
404	          if (self) shooter.tally.selfDamage += dealt;
405	          else {
406	            shooter.tally.hits++;
407	            shooter.tally.damageDealt += dealt;
408	            if (b.bounced) shooter.tally.ricochetHits++;
409	          }
410	          damageTank(round, t, b.damage, events, {
411	            cause: self ? 'self' : 'bullet',
412	            by: b.owner,
413	            ricochet: b.bounced,
414	            bx: b.x,
415	            by_: b.y,
416	            dirx: b.vx / speed,
417	            diry: b.vy / speed,
418	          });
419	          break;
420	        }
421	      }
422	    }
423	  }
424	  // Bullets destroy each other: shooting down an incoming round is allowed.
425	  const live = round.bullets.filter((b) => !b.dead);
426	  for (let i = 0; i < live.length; i++) {
427	    for (let j = i + 1; j < live.length; j++) {
428	      const a = live[i];
429	      const b = live[j];
430	      if (a.dead || b.dead) continue;
431	      if (Math.hypot(a.x - b.x, a.y - b.y) < BULLET_RADIUS * 2 + 2) {
432	        a.dead = true;
433	        b.dead = true;
434	        if (a.owner !== b.owner) {
435	          // Credit the interception to whoever's bullet was fired later (the defensive shot).
436	          const later = a.id > b.id ? a : b;
437	          round.tanks[later.owner].tally.intercepts++;
438	        }
439	        events.push({ type: 'clash', x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
440	      }
441	    }
442	  }
443	  round.bullets = round.bullets.filter((b) => !b.dead);
444	}
445	
446	function stepKits(round, events) {
447	  for (const k of round.kits) {
448	    if (!k.active) {
449	      k.respawnIn = Math.max(0, k.respawnIn - DT);
450	      if (k.respawnIn === 0) {
451	        k.active = true;
452	        events.push({ type: 'kitSpawn', x: k.x, y: k.y });
453	      }
454	      continue;
455	    }
456	    let best = null;
457	    let bestD = Infinity;
458	    let tie = false;
459	    for (const t of round.tanks) {
460	      if (!t.alive) continue;
461	      const d = Math.hypot(t.x - k.x, t.y - k.y);
462	      if (d > TANK_RADIUS + KIT.radius) continue;
463	      if (Math.abs(d - bestD) < 1e-9) tie = true;
464	      else if (d < bestD) {
465	        best = t;
466	        bestD = d;
467	        tie = false;
468	      }
469	    }
470	    if (best && !tie) {
471	      const healed = Math.min(KIT.heal, best.stats.maxHp - best.hp);
472	      best.hp += healed;
473	      best.tally.kits++;
474	      k.active = false;
475	      k.respawnIn = KIT.respawn;
476	      events.push({ type: 'pickup', side: best.side, x: k.x, y: k.y, healed });
477	    }
478	  }
479	}
480	
481	// Advance one tick. actions[side] = { throttle, turn, turretTurn, fire }.
482	export function stepRound(round, actions) {
483	  if (round.over) return [];
484	  const events = [];
485	  const acts = [sanitizeAction(actions[0]), sanitizeAction(actions[1])];
486	
487	  for (const t of round.tanks) {
488	    if (!t.alive) continue;
489	    t.reloadLeft = Math.max(0, t.reloadLeft - DT);
490	    moveTank(round, t, acts[t.side]);
491	  }
492	  for (const t of round.tanks) if (t.alive) resolveTankWalls(round, t, events);
493	  resolveTankTank(round.tanks[0], round.tanks[1]);
494	  for (const t of round.tanks) if (t.alive) resolveTankWalls(round, t, events);
495	
496	  for (const t of round.tanks) {
497	    if (t.alive && acts[t.side].fire && t.reloadLeft <= 0) fire(round, t, events);
498	  }
499	
500	  stepBullets(round, events);
501	  stepKits(round, events);
502	
503	  const prevRadius = round.zone.radius;
504	  round.zone.radius = zoneRadiusAt(round.time + DT);
505	  if (prevRadius === ZONE_START_RADIUS && round.zone.radius < prevRadius) events.push({ type: 'zoneStart' });
506	  for (const t of round.tanks) {
507	    if (!t.alive) continue;
508	    if (Math.hypot(t.x - round.zone.x, t.y - round.zone.y) > round.zone.radius) {
509	      const dmg = ZONE.damagePerSecond * DT;
510	      t.tally.zoneDamage += Math.min(t.hp, dmg);
511	      damageTank(round, t, dmg, events, { cause: 'zone', quiet: true });
512	    }
513	  }
514	
515	  round.tick++;
516	  round.time = round.tick * DT;
517	
518	  const [a, b] = round.tanks;
519	  if (!a.alive || !b.alive) {
520	    round.over = true;
521	    round.endReason = 'kill';
522	    round.winner = !a.alive && !b.alive ? null : a.alive ? 0 : 1;
523	  } else if (round.time >= ROUND_SECONDS - 1e-9) {
524	    round.over = true;
525	    round.endReason = 'time';
526	    const fa = a.hp / a.stats.maxHp;
527	    const fb = b.hp / b.stats.maxHp;
528	    round.winner = Math.abs(fa - fb) < 1e-9 ? null : fa > fb ? 0 : 1;
529	  }
530	  if (round.over) events.push({ type: 'roundOver', winner: round.winner, reason: round.endReason });
531	  return events;
532	}
