1	// Sparring bot "Охотник": grid pathfinding, lead aiming, simple dodging,
2	// picks up repair kits and respects the zone. A fair baseline, not a champion.
3	
4	const CELL = 25;
5	const PAD = 26; // tank radius + margin
6	let grid = null;
7	let gridMap = null;
8	let path = [];
9	let pathTick = -999;
10	
11	const norm = (a) => Math.atan2(Math.sin(a), Math.cos(a));
12	const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
13	
14	function segHitsRect(x1, y1, x2, y2, r, pad) {
15	  const minX = r.x - pad, maxX = r.x + r.w + pad, minY = r.y - pad, maxY = r.y + r.h + pad;
16	  let t0 = 0, t1 = 1;
17	  const dx = x2 - x1, dy = y2 - y1;
18	  const clip = (p, q) => {
19	    if (Math.abs(p) < 1e-12) return q >= 0;
20	    const t = q / p;
21	    if (p < 0) { if (t > t1) return false; if (t > t0) t0 = t; }
22	    else { if (t < t0) return false; if (t < t1) t1 = t; }
23	    return true;
24	  };
25	  return clip(-dx, x1 - minX) && clip(dx, maxX - x1) && clip(-dy, y1 - minY) && clip(dy, maxY - y1);
26	}
27	
28	function clear(walls, x1, y1, x2, y2, pad) {
29	  return !walls.some((w) => segHitsRect(x1, y1, x2, y2, w, pad));
30	}
31	
32	function buildGrid(arena) {
33	  const cols = Math.ceil(arena.width / CELL), rows = Math.ceil(arena.height / CELL);
34	  const g = { cols, rows, free: new Uint8Array(cols * rows) };
35	  for (let r = 0; r < rows; r++) {
36	    for (let c = 0; c < cols; c++) {
37	      const x = c * CELL + CELL / 2, y = r * CELL + CELL / 2;
38	      const inBounds = x > PAD && x < arena.width - PAD && y > PAD && y < arena.height - PAD;
39	      const hit = arena.walls.some((w) => x > w.x - PAD && x < w.x + w.w + PAD && y > w.y - PAD && y < w.y + w.h + PAD);
40	      g.free[r * cols + c] = inBounds && !hit ? 1 : 0;
41	    }
42	  }
43	  return g;
44	}
45	
