1	#!/usr/bin/env node
2	// Sandbox: run your tank against sparring bots without a browser.
3	//   node arena/cli.mjs                      -> tank/ vs hunter, 8 rounds (all maps, both sides)
4	//   node arena/cli.mjs --vs dummy --rounds 4
5	//   node arena/cli.mjs --vs tank            -> mirror match against yourself
6	//   node arena/cli.mjs --map Каньон --verbose
7	import { existsSync } from 'node:fs';
8	import { dirname, join, resolve } from 'node:path';
9	import { fileURLToPath, pathToFileURL } from 'node:url';
10	import { performance } from 'node:perf_hooks';
11	import {
12	  MAPS, STAT_POINTS, checkStats, createRound, stepRound, botView, roundPlan, DT,
13	} from './engine.js';
14	
15	const here = dirname(fileURLToPath(import.meta.url));
16	const root = resolve(here, '..');
17	
18	function parseArgs(argv) {
19	  const opts = { tank: 'tank', vs: 'hunter', rounds: 8, map: null, verbose: false };
20	  const rest = [];
21	  for (let i = 0; i < argv.length; i++) {
22	    const a = argv[i];
23	    if (a === '--vs') opts.vs = argv[++i];
24	    else if (a === '--rounds') opts.rounds = Number(argv[++i]);
25	    else if (a === '--map') opts.map = argv[++i];
26	    else if (a === '--verbose' || a === '-v') opts.verbose = true;
27	    else if (a === '--help' || a === '-h') opts.help = true;
28	    else rest.push(a);
29	  }
30	  if (rest[0]) opts.tank = rest[0];
31	  return opts;
32	}
33	
34	function resolveBotDir(spec) {
35	  const candidates = [resolve(process.cwd(), spec), resolve(root, spec), join(here, 'sparring', spec)];
36	  for (const c of candidates) if (existsSync(join(c, 'bot.js'))) return c;
37	  throw new Error(`Не нашёл bot.js для «${spec}». Искал: ${candidates.join(', ')}`);
38	}
39	
40	async function loadBot(dir, instance) {
41	  // The query string gives each side its own module instance (mirror matches).
42	  const url = pathToFileURL(join(dir, 'bot.js')).href + `?instance=${instance}`;
43	  const mod = await import(url);
44	  const bot = mod.default ?? mod;
45	  if (!bot || typeof bot.tick !== 'function') throw new Error(`${dir}/bot.js: нет export default { tick(state) { ... } }`);
46	  const check = checkStats(bot.stats);
47	  if (!check.ok) throw new Error(`${dir}/bot.js: неверные stats — ${check.error} (всего ${STAT_POINTS} очков, каждое 0..5)`);
48	  return { bot, dir, name: String(bot.name || 'Без имени'), errors: 0, timeMax: 0, timeSum: 0, calls: 0 };
49	}
50	
51	function callBot(entry, fn, arg) {
52	  const t0 = performance.now();
53	  try {
54	    return entry.bot[fn]?.(arg);
55	  } catch (err) {
56	    entry.errors++;
57	    if (entry.errors <= 3) console.error(`  ! ${entry.name}.${fn} бросил ошибку: ${err?.stack || err}`);
58	    return null;
59	  } finally {
60	    const dt = performance.now() - t0;
61	    if (fn === 'tick') {
62	      entry.timeMax = Math.max(entry.timeMax, dt);
63	      entry.timeSum += dt;
64	      entry.calls++;
65	    }
66	  }
67	}
68	
69	const pct = (a, b) => (b ? Math.round((100 * a) / b) + '%' : '—');
70	
71	async function main() {
72	  const opts = parseArgs(process.argv.slice(2));
73	  if (opts.help) {
74	    console.log('node arena/cli.mjs [папка-танка=tank] [--vs hunter|dummy|tank|путь] [--rounds 8] [--map имя] [--verbose]');
75	    return;
76	  }
77	  const me = await loadBot(resolveBotDir(opts.tank), 0);
78	  const foe = await loadBot(resolveBotDir(opts.vs), 1);
79	  const mapFilter = opts.map
80	    ? MAPS.findIndex((m, i) => m.name.toLowerCase() === opts.map.toLowerCase() || String(i) === opts.map)
81	    : -1;
82	  if (opts.map && mapFilter < 0) throw new Error(`Нет карты «${opts.map}». Есть: ${MAPS.map((m) => m.name).join(', ')}`);
83	
84	  console.log(`\n${me.name}  vs  ${foe.name}   (${opts.rounds} раундов)\n`);
85	  const score = { win: 0, loss: 0, draw: 0 };
86	  const total = { dealt: 0, taken: 0, shots: 0, hits: 0, self: 0 };
87	
88	  for (let i = 0; i < opts.rounds; i++) {
89	    const plan = roundPlan(i);
90	    const mapIndex = mapFilter >= 0 ? mapFilter : plan.mapIndex;
91	    const mySide = plan.swap ? 1 : 0;
92	    const bySide = mySide === 0 ? [me, foe] : [foe, me];
93	    const round = createRound({ mapIndex, tanks: bySide.map((e) => ({ name: e.name, stats: e.bot.stats })) });
94	    for (let s = 0; s < 2; s++) {
95	      callBot(bySide[s], 'init', {
96	        round: i, side: s, mapName: round.map.name, view: botView(round, s),
97	      });
98	    }
99	    while (!round.over) {
100	      const actions = [0, 1].map((s) => callBot(bySide[s], 'tick', botView(round, s)));
101	      const events = stepRound(round, actions);
102	      if (opts.verbose) {
